/* Golden vectors generated by an independent Python implementation of the
 * syntax-element order and Exp-Golomb mappings in
 * reference/x264/encoder/encoder.c:213-364 (slice_header_write), with defaults
 * from :122-211 (slice_header_init).  That generator was cross-checked
 * bit-for-bit against the IDR slice NAL emitted by build/x264_ref/x264.exe:
 * decoding the reference header's fields and re-encoding them reproduced all
 * 24 header bits exactly.
 *
 * SHADER: C — the same serial entropy-stage bitstream as the SPS/PPS tests.
 */
#include "phx_slice.h"
#include <stdio.h>
#include <string.h>

static int fails = 0;
#define CHECK(cond,msg) do { if (!(cond)) { \
    printf("FAIL %s (line %d)\n",msg,__LINE__); ++fails; } } while (0)

/* Expected bytes come from the source formulas; the last byte may contain
 * only padding, so compare exactly (want_bits+7)/8 bytes and the bit count. */
static void verify(const char *label, phx_bs_t *bs, const uint8_t *buf,
                   const uint8_t *want, int want_bits)
{
    int n = (want_bits + 7) / 8;
    if (phx_bs_pos(bs) != want_bits || memcmp(buf, want, (size_t)n) != 0) {
        printf("FAIL %s: %d bits (want %d), bytes ", label, phx_bs_pos(bs), want_bits);
        for (int i = 0; i < n; i++) printf("%02X", buf[i]);
        printf(" (want ");
        for (int i = 0; i < n; i++) printf("%02X", want[i]);
        printf(")\n");
        ++fails;
    }
}

/* IDR I slice, poc type 0: first_mb=0, idr_pic_id=0, poc=0, qp_delta=0,
 * deblocking enabled with zero offsets (encoder.c:223/225/226/227/237/241/
 * 332/333/353/357/360/361). */
static const uint8_t gold_idr_i[] = { 0x88, 0x84, 0x0F };
static const int gold_idr_i_bits = 24;

/* P reference slice: first_mb=3, frame_num=11, poc=22, num_ref_idx override,
 * L0 reordering, explicit pred_weight_table, MMCO, CABAC init 2, qp_delta=3,
 * alpha=2/beta=-2 (encoder.c:254-345, :351-361). */
static const uint8_t gold_p_ref[] = {
    0x21, 0xB6, 0xD7, 0x4F, 0x46, 0x27, 0x45, 0xAD,
    0x16, 0x65, 0x35, 0xB3, 0x48, 0x50
};
static const int gold_p_ref_bits = 108;

/* B non-reference slice, poc type 2 (no POC bits): direct_spatial, both ref
 * lists reordered, cabac_init_idc=0, qp_delta=-4, deblocking disabled
 * (encoder.c:239/250/254-288/351-357). */
static const uint8_t gold_b_nonref[] = {
    0x9E, 0xBA, 0xD1, 0x28, 0x95, 0x24, 0x4A
};
static const int gold_b_nonref_bits = 56;

/* CAVLC I slice with two slice groups: slice_group_change_cycle=13 in
 * Ceil(Log2(8*8))=6 bits after the deblocking fields (H.264 7.3.3). */
static const uint8_t gold_fmo_cycle[] = { 0x88, 0xBA, 0xE6, 0x80 };
static const int gold_fmo_cycle_bits = 25;

/* MBAFF first_mb mapping, field flags, delta_poc_bottom=-1, idr_pic_id=1
 * (encoder.c:215-221/231/233/237/243/332/333). */
static const uint8_t gold_field_idr[] = { 0x42, 0x25, 0xA9, 0x28 };
static const int gold_field_idr_bits = 30;

int main(void)
{
    phx_param_t param;
    phx_param_default(&param);                      /* base.c:344 medium */

    phx_sps_t sps;
    memset(&sps, 0, sizeof(sps));
    sps.i_id = 0;
    sps.i_mb_width = 4; sps.i_mb_height = 4;        /* 64x64 */
    sps.i_log2_max_frame_num = 4;                   /* set.c:169 */
    sps.i_poc_type = 0;                             /* set.c:173 (bframes > 0) */
    sps.i_log2_max_poc_lsb = 4;
    sps.b_frame_mbs_only = 1;
    sps.i_chroma_format_idc = 1;

    phx_pps_t pps;
    memset(&pps, 0, sizeof(pps));
    pps.i_id = 0; pps.i_sps_id = 0;
    pps.b_cabac = 1;
    pps.i_num_slice_groups = 1;                     /* set.c:486 */
    pps.b_weighted_pred = 1;
    pps.b_weighted_bipred = 2;                      /* set.c:492 */
    pps.i_pic_init_qp = 26;
    pps.b_deblocking_filter_control = 1;            /* set.c:498 */

    phx_slice_frame_t f;
    phx_slice_header_t sh;
    uint8_t buf[64];
    phx_bs_t bs;

    /* --- case A: IDR I --- */
    memset(&f, 0, sizeof(f));
    f.i_first_mb = 0; f.i_last_mb = 15;
    f.i_frame_num = 0; f.i_poc = 0;
    f.b_idr = 1; f.i_idr_pic_id = 0; f.i_nal_ref_idc = 3;
    f.i_type = PHX_SLICE_I; f.i_qp = 26;
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    CHECK(sh.i_qp_delta == 0, "init qp_delta / encoder.c:199");
    CHECK(sh.i_idr_pic_id == 0 && sh.i_disable_deblocking_filter_idc == 0,
          "init idr/deblock / encoder.c:142,203-208");
    phx_bs_init(&bs, buf, sizeof(buf));
    phx_slice_header_write(&bs, &param, &sh);
    verify("IDR I", &bs, buf, gold_idr_i, gold_idr_i_bits);

    /* --- case B: P reference with all optional fields --- */
    f.i_first_mb = 3; f.i_frame_num = 11; f.i_poc = 22;
    f.b_idr = 0; f.i_idr_pic_id = -1; f.i_nal_ref_idc = 2;
    f.i_type = PHX_SLICE_P; f.i_qp = 29;
    f.i_deblocking_filter_alphac0 = 2;              /* doubled at encoder.c:209 */
    f.i_deblocking_filter_beta = -2;                /* doubled at encoder.c:210 */
    f.b_ref_reorder[0] = 1;                         /* encoder.c:177 */
    f.i_ref[0] = 3;                                 /* encoder.c:186 */
    f.ref_frame_num[0][0] = 14;                     /* diff +3 -> idc 1, arg 2 */
    f.ref_frame_num[0][1] = 13;                     /* diff -1 -> idc 0, arg 0 */
    f.ref_frame_num[0][2] = 19;                     /* diff +6 -> idc 1, arg 5 */
    f.i_cabac_init_idc = 2;                         /* encoder.c:196 */
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    CHECK(sh.ref_pic_list_order[0][0].idc == 1 && sh.ref_pic_list_order[0][0].arg == 2 &&
          sh.ref_pic_list_order[0][1].idc == 0 && sh.ref_pic_list_order[0][1].arg == 0 &&
          sh.ref_pic_list_order[0][2].idc == 1 && sh.ref_pic_list_order[0][2].arg == 5,
          "init reorder / encoder.c:180-194");
    sh.b_num_ref_idx_override = 1;                  /* encoder.c:254 */
    sh.i_num_ref_idx_l0_active = 3;                 /* encoder.c:257 */
    sh.i_num_ref_idx_l1_active = 2;                 /* unused for P */
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            sh.weight[i][j].i_denom = 0;            /* encoder.c:296/298 */
    sh.weight[0][0].b_weighted = 1; sh.weight[0][0].i_scale =  1; sh.weight[0][0].i_offset = -2;
    sh.weight[0][1].b_weighted = 1; sh.weight[0][1].i_scale =  1; sh.weight[0][1].i_offset =  0;
    sh.weight[0][2].b_weighted = 1; sh.weight[0][2].i_scale =  0; sh.weight[0][2].i_offset =  1;
    sh.weight[2][0].b_weighted = 1; sh.weight[2][0].i_scale = -1; sh.weight[2][0].i_offset =  3;
    sh.i_mmco_command_count = 2;                    /* encoder.c:337 */
    sh.mmco_diff[0] = 3; sh.mmco_diff[1] = 1;       /* writes 2 and 0 (:343) */
    phx_bs_init(&bs, buf, sizeof(buf));
    phx_slice_header_write(&bs, &param, &sh);
    verify("P ref + weights/MMCO", &bs, buf, gold_p_ref, gold_p_ref_bits);

    /* --- case C: B non-reference, POC type 2 --- */
    sps.i_poc_type = 2;                             /* set.c:173 (bframes == 0) */
    memset(&f, 0, sizeof(f));
    f.i_first_mb = 0; f.i_last_mb = 15;
    f.i_frame_num = 5; f.i_poc = 0;
    f.b_idr = 0; f.i_nal_ref_idc = 0;
    f.i_type = PHX_SLICE_B; f.i_qp = 22;            /* pic_init_qp-4 */
    f.b_direct_spatial_mv_pred = 1;                 /* encoder.c:250 */
    f.b_ref_reorder[0] = 1; f.i_ref[0] = 2;
    f.ref_frame_num[0][0] = 9;                      /* diff +4 -> idc 1, arg 3 */
    f.ref_frame_num[0][1] = 7;                      /* diff -2 -> idc 0, arg 1 */
    f.b_ref_reorder[1] = 1; f.i_ref[1] = 1;
    f.ref_frame_num[1][0] = 6;                      /* diff +1 -> idc 1, arg 0 */
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    sh.b_num_ref_idx_override = 1;
    sh.i_num_ref_idx_l0_active = 2;
    sh.i_num_ref_idx_l1_active = 1;
    sh.i_cabac_init_idc = 0;                        /* encoder.c:351 */
    sh.i_disable_deblocking_filter_idc = 1;         /* encoder.c:357 */
    phx_bs_init(&bs, buf, sizeof(buf));
    phx_slice_header_write(&bs, &param, &sh);
    verify("B non-ref", &bs, buf, gold_b_nonref, gold_b_nonref_bits);

    /* --- case D: FMO slice_group_change_cycle --- */
    sps.i_mb_width = 8; sps.i_mb_height = 8;        /* PicSizeInMapUnits = 64 */
    pps.i_num_slice_groups = 2;                     /* not produced by x264 */
    pps.b_cabac = 0;                                /* CAVLC I slice */
    memset(&f, 0, sizeof(f));
    f.i_last_mb = 63;
    f.i_frame_num = 7; f.i_poc = 0;
    f.b_idr = 0; f.i_nal_ref_idc = 0;
    f.i_type = PHX_SLICE_I; f.i_qp = 27;
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    sh.i_slice_group_change_cycle = 13;
    CHECK(phx_slice_group_change_bits(&sps) == 6, "ceil_log2(64)");
    phx_bs_init(&bs, buf, sizeof(buf));
    phx_slice_header_write(&bs, &param, &sh);
    verify("FMO cycle", &bs, buf, gold_fmo_cycle, gold_fmo_cycle_bits);

    /* --- case E: MBAFF/field first_mb + delta_poc_bottom --- */
    sps.i_mb_width = 4; sps.i_mb_height = 4;
    sps.i_poc_type = 0; sps.b_frame_mbs_only = 0;
    pps.b_cabac = 1; pps.i_num_slice_groups = 1; pps.b_pic_order = 1;
    memset(&f, 0, sizeof(f));
    f.i_first_mb = 5; f.i_last_mb = 15;
    f.i_frame_num = 2; f.i_poc = 9;
    f.b_idr = 1; f.i_idr_pic_id = 1; f.i_nal_ref_idc = 3;
    f.i_type = PHX_SLICE_I; f.i_qp = 26;
    f.b_mbaff = 1;                                  /* encoder.c:138 */
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    sh.b_field_pic = 1;                             /* encoder.c:231 (caller override) */
    sh.b_bottom_field = 1;                          /* encoder.c:233 */
    sh.i_delta_poc_bottom = -1;                     /* encoder.c:243 */
    sh.i_disable_deblocking_filter_idc = 1;
    phx_bs_init(&bs, buf, sizeof(buf));
    phx_slice_header_write(&bs, &param, &sh);
    verify("MBAFF field IDR", &bs, buf, gold_field_idr, gold_field_idr_bits);

    /* The global deblocking switch must force disable idc 1 (encoder.c:205). */
    param.b_deblocking_filter = 0;
    phx_slice_header_init(&sh, &param, &sps, &pps, &f);
    CHECK(sh.i_disable_deblocking_filter_idc == 1, "deblocking off / encoder.c:208");

    printf("%s: slice header, %d failures\n", fails ? "FAILED" : "OK", fails);
    return fails ? 1 : 0;
}
